// =====================================================================
// EDITOR VISUALE (VANILLA WEB COMPONENT - ZERO EXTERNAL DEPS)
// =====================================================================
class DreameVacuumCardEditor extends HTMLElement {
  constructor() {
    super();
    this.attachShadow({ mode: 'open' });
    this._config = {};
    this._hass = null;
  }

  setConfig(config) {
    this._config = config ? { ...config } : {};
    this._render();
  }

  set hass(hass) {
    this._hass = hass;
    const form = this.shadowRoot.querySelector('ha-form');
    if (form) form.hass = hass;
  }

  get _schema() {
    return [
      {
        name: 'entity',
        label: 'Entità Robot Aspirapolvere (es. vacuum.dreame_l10_ultra)',
        required: true,
        selector: { entity: { domain: ['vacuum'] } }
      },
      {
        name: 'error_entity',
        label: 'Sensore Errore (es. sensor.dreame_l10_ultra_errore)',
        required: false,
        selector: { entity: { domain: ['sensor'] } }
      },
      {
        name: 'cleaning_mode_entity',
        label: 'Selettore Modalità Pulizia (es. select.dreame_l10_ultra_modalita_pulizia)',
        required: false,
        selector: { entity: { domain: ['select', 'input_select', 'sensor'] } }
      }
    ];
  }

  _valueChanged(ev) {
    if (!this._config || !ev.detail) return;
    const newConfig = { ...this._config, ...ev.detail.value };
    this._config = newConfig;
    this.dispatchEvent(new CustomEvent('config-changed', {
      detail: { config: newConfig },
      bubbles: true,
      composed: true
    }));
  }

  _setTestMode(val) {
    const newConfig = { ...this._config };
    if (val) {
      newConfig.test_mode = val;
    } else {
      delete newConfig.test_mode;
    }
    this._config = newConfig;
    this.dispatchEvent(new CustomEvent('config-changed', {
      detail: { config: newConfig },
      bubbles: true,
      composed: true
    }));
    this._render();
  }

  _render() {
    const currentTestMode = this._config?.test_mode || '';
    this.shadowRoot.innerHTML = `
      <style>${EDITOR_STYLES}</style>
      <div id="form-container"></div>
      <div class="test-panel">
        <div class="test-header">
          <div class="test-title">🧪 Modalità Test / Anteprima Rapida Stati</div>
          <div class="test-desc">Simula all'istante gli stati del robot e gli errori per verificare il rendering:</div>
        </div>
        <div class="test-grid">
          <button type="button" class="test-btn ${currentTestMode === '' ? 'active' : ''}" data-mode="">
            🔄 Reale (Sensori)
          </button>
          <button type="button" class="test-btn ${currentTestMode === 'cleaning_both' ? 'active' : ''}" data-mode="cleaning_both">
            🌀 Lavaggio: Aspira e lava
          </button>
          <button type="button" class="test-btn ${currentTestMode === 'cleaning_sweep' ? 'active' : ''}" data-mode="cleaning_sweep">
            🧹 Lavaggio: Solo aspira
          </button>
          <button type="button" class="test-btn ${currentTestMode === 'cleaning_mop' ? 'active' : ''}" data-mode="cleaning_mop">
            💧 Lavaggio: Solo lava
          </button>
          <button type="button" class="test-btn ${currentTestMode === 'returning' ? 'active' : ''}" data-mode="returning">
            ⬇️ Ritorno alla base
          </button>
          <button type="button" class="test-btn ${currentTestMode === 'docked' ? 'active' : ''}" data-mode="docked">
            🏠 In base (Docked)
          </button>
          <button type="button" class="test-btn ${currentTestMode === 'paused' ? 'active' : ''}" data-mode="paused">
            ⏸️ In pausa
          </button>
          <button type="button" class="test-btn err ${currentTestMode === 'err_mops' ? 'active' : ''}" data-mode="err_mops">
            🚨 Errore: Panni staccati (69/70)
          </button>
          <button type="button" class="test-btn err ${currentTestMode === 'err_wheels' ? 'active' : ''}" data-mode="err_wheels">
            🚨 Errore: Ruote sollevate (1/6)
          </button>
          <button type="button" class="test-btn err ${currentTestMode === 'err_route' ? 'active' : ''}" data-mode="err_route">
            🚨 Errore: Zona non raggiungibile (61/62)
          </button>
          <button type="button" class="test-btn err ${currentTestMode === 'err_washboard' ? 'active' : ''}" data-mode="err_washboard">
            🚨 Errore: Asse lavaggio mocio (124/119)
          </button>
          <button type="button" class="test-btn err ${currentTestMode === 'err_clean_water' ? 'active' : ''}" data-mode="err_clean_water">
            🚨 Errore: Acqua pulita (105)
          </button>
        </div>
      </div>
    `;

    const container = this.shadowRoot.getElementById('form-container');
    if (container) {
      const form = document.createElement('ha-form');
      form.hass = this._hass;
      form.data = this._config;
      form.schema = this._schema;
      form.computeLabel = s => s.label || s.name;
      form.addEventListener('value-changed', ev => this._valueChanged(ev));
      container.appendChild(form);
    }

    const btns = this.shadowRoot.querySelectorAll('.test-btn');
    btns.forEach(b => {
      b.addEventListener('click', () => {
        this._setTestMode(b.getAttribute('data-mode'));
      });
    });
  }
}

// =====================================================================
// CARD PRINCIPALE DREAME VACUUM (VANILLA WEB COMPONENT - ZERO EXTERNAL DEPS)
// =====================================================================
class DreameVacuumCard extends HTMLElement {
  constructor() {
    super();
    this.attachShadow({ mode: 'open' });
    this._config = null;
    this._hass = null;
    this._lastStateString = '';
  }

  static getGridOptions() {
    return {
      columns: 6,
      min_columns: 6,
      max_columns: 12,
      rows: 5,
      min_rows: 5
    };
  }

  getGridOptions() {
    return {
      columns: 6,
      min_columns: 6,
      max_columns: 12,
      rows: 5,
      min_rows: 5
    };
  }

  getCardSize() {
    return 5;
  }

  static getConfigElement() {
    return document.createElement('dreame-vacuum-card-state-and-error-editor');
  }

  static getStubConfig() {
    return {
      entity: 'vacuum.dreame_l10_ultra',
      error_entity: 'sensor.dreame_l10_ultra_errore',
      cleaning_mode_entity: 'select.dreame_l10_ultra_modalita_pulizia'
    };
  }

  setConfig(config) {
    if (!config.test_mode && !config.entity) {
      throw new Error("Specificare l'entità del robot aspirapolvere (entity).");
    }
    this._config = config;
    this._render();
  }

  set hass(hass) {
    this._hass = hass;
    this._render();
  }

  _parseError(errObj) {
    if (!errObj) return null;

    const rawVal = errObj.attributes?.value ?? errObj.attributes?.code ?? errObj.state;
    const num = parseInt(rawVal, 10);
    const text = String(errObj.state || '').trim().toLowerCase();

    if (num === 0 || text === '0' || text === 'nessun errore' || text === 'no_error' || text === 'ok' || text === 'none' || text === '') {
      return null;
    }

    if (num === 69 || num === 70 || text.includes('panni') || text.includes('mop')) {
      return {
        key: 'panni_staccati',
        msg: 'I panni si sono staccati',
        img: IMAGES.ERR_MOPS
      };
    }

    if (num === 1 || num === 6 || text.includes('ruote') || text.includes('sollevat') || text.includes('suolo') || text.includes('drop')) {
      return {
        key: 'ruote_sollevate',
        msg: 'Le ruote non sono a contatto con il suolo',
        img: IMAGES.ERR_WHEELS
      };
    }

    if (num === 61 || num === 62 || text.includes('raggiungibil') || text.includes('percorso') || text.includes('route') || text.includes('bloccato')) {
      return {
        key: 'zona_non_raggiungibile',
        msg: 'Zona non raggiungibile',
        img: IMAGES.ERR_ROUTE
      };
    }

    if (num === 124 || num === 119 || text.includes('asse') || text.includes('lavaggio') || text.includes('washboard')) {
      return {
        key: 'asse_lavaggio_mocio',
        msg: "Pulire l'asse di lavaggio del mocio",
        img: IMAGES.ERR_WASHBOARD
      };
    }

    if (num === 105 || num === 107 || num === 213 || text.includes('acqua pulita') || text.includes('riempire') || text.includes('clean_water') || text.includes('clean_tank') || text.includes('waterbox')) {
      return {
        key: 'serbatoio_acqua_pulita',
        msg: "Si prega di riempire il serbatoio dell'acqua pulita",
        img: IMAGES.ERR_CLEAN_WATER
      };
    }

    return {
      key: 'generico',
      msg: errObj.state || 'Errore robot',
      img: IMAGES.ERR_ROUTE
    };
  }

  _parseCleaningMode(modeState) {
    if (!modeState) return { label: 'Aspira e lava', icon: 'both' };

    const raw = String(modeState).trim();
    const low = raw.toLowerCase();

    const isSweep = low.includes('aspira') || low.includes('sweep') || low.includes('vacuum');
    const isMop = low.includes('lava') || low.includes('mop');

    if (isSweep && isMop) {
      return { label: raw, icon: 'both' };
    } else if (isSweep) {
      return { label: raw, icon: 'sweep' };
    } else if (isMop) {
      return { label: raw, icon: 'mop' };
    }
    return { label: raw, icon: 'both' };
  }

  _handleMoreInfo(entityId) {
    if (!entityId) return;
    const event = new CustomEvent('hass-more-info', {
      bubbles: true,
      composed: true,
      detail: { entityId }
    });
    this.dispatchEvent(event);
  }

  _render() {
    if (!this._config) return;

    let robotState = 'docked';
    let activeError = null;
    let cleaningMode = { label: 'Aspira e lava', icon: 'both' };

    const tm = this._config.test_mode;

    if (tm) {
      if (tm === 'cleaning_both') {
        robotState = 'cleaning';
        cleaningMode = { label: 'Aspira e lava', icon: 'both' };
      } else if (tm === 'cleaning_sweep') {
        robotState = 'cleaning';
        cleaningMode = { label: 'Solo aspirazione', icon: 'sweep' };
      } else if (tm === 'cleaning_mop') {
        robotState = 'cleaning';
        cleaningMode = { label: 'Solo lavaggio', icon: 'mop' };
      } else if (tm === 'returning') {
        robotState = 'returning';
      } else if (tm === 'docked') {
        robotState = 'docked';
      } else if (tm === 'paused') {
        robotState = 'paused';
      } else if (tm === 'err_mops') {
        activeError = { key: 'panni_staccati', msg: 'I panni si sono staccati', img: IMAGES.ERR_MOPS };
      } else if (tm === 'err_wheels') {
        activeError = { key: 'ruote_sollevate', msg: 'Le ruote non sono a contatto con il suolo', img: IMAGES.ERR_WHEELS };
      } else if (tm === 'err_route') {
        activeError = { key: 'zona_non_raggiungibile', msg: 'Zona non raggiungibile', img: IMAGES.ERR_ROUTE };
      } else if (tm === 'err_washboard') {
        activeError = { key: 'asse_lavaggio_mocio', msg: "Pulire l'asse di lavaggio del mocio", img: IMAGES.ERR_WASHBOARD };
      } else if (tm === 'err_clean_water') {
        activeError = { key: 'serbatoio_acqua_pulita', msg: "Si prega di riempire il serbatoio dell'acqua pulita", img: IMAGES.ERR_CLEAN_WATER };
      }
    } else if (this._hass) {
      const vacObj = this._config.entity ? this._hass.states[this._config.entity] : null;
      const errObj = this._config.error_entity ? this._hass.states[this._config.error_entity] : null;
      const modeObj = this._config.cleaning_mode_entity ? this._hass.states[this._config.cleaning_mode_entity] : null;

      activeError = this._parseError(errObj);

      if (vacObj) {
        const s = String(vacObj.state).toLowerCase();
        if (s === 'cleaning' || s === 'sweeping' || s === 'mopping' || s === 'sweeping_and_mopping') {
          robotState = 'cleaning';
        } else if (s === 'returning' || s === 'returning_to_base') {
          robotState = 'returning';
        } else if (s === 'docked') {
          robotState = 'docked';
        } else if (s === 'paused') {
          robotState = 'paused';
        } else if (s === 'error') {
          robotState = 'error';
          if (!activeError) {
            activeError = {
              key: 'generico',
              msg: vacObj.attributes?.error || 'Errore robot',
              img: IMAGES.ERR_ROUTE
            };
          }
        } else {
          robotState = s;
        }
      }

      if (modeObj) {
        cleaningMode = this._parseCleaningMode(modeObj.state);
      }
    }

    const currentStateString = JSON.stringify({
      tm,
      robotState,
      activeError: activeError ? activeError.key : null,
      cleaningMode
    });

    if (this._lastStateString === currentStateString) {
      return;
    }
    this._lastStateString = currentStateString;

    let visualHtml = '';
    let topHtml = '';

    if (activeError) {
      topHtml = `
        <span class="b">Errore</span>
        <p class="m">${activeError.msg}</p>
      `;
      visualHtml = `<img src="${activeError.img}" alt="${activeError.msg}" class="e" />`;
    } else if (robotState === 'returning') {
      topHtml = `
        <span class="k">
          <svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"><path d="M12 5v14M19 12l-7 7-7-7"/></svg>
          Ritorno alla base
        </span>
      `;
      visualHtml = `
        <div class="returning-wrap">
          <img src="${IMAGES.ROBOT_RETURNING}" alt="Robot in ritorno alla base" width="124" />
          <div class="arrow-down"></div>
        </div>
      `;
    } else if (robotState === 'docked') {
      topHtml = `
        <span class="k">
          <svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M3 9l9-7 9 7v11a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2z"/></svg>
          In base
        </span>
      `;
      visualHtml = `
        <div class="dock-circle">
          <img src="${IMAGES.ROBOT_DOCKED}" alt="Robot in base" width="96" class="robot-docked-img" />
          <div class="dock-station-outline"></div>
        </div>
      `;
    } else if (robotState === 'paused') {
      topHtml = `
        <span class="k">
          <svg width="12" height="12" viewBox="0 0 24 24" fill="currentColor"><path d="M6 19h4V5H6v14zm8-14v14h4V5h-4z"/></svg>
          In pausa
        </span>
      `;
      visualHtml = `
        <img src="${IMAGES.ROBOT_CLEANING}" alt="Robot in pausa" width="124" class="robot-paused" />
      `;
    } else {
      let modeIconSvg = '';
      if (cleaningMode.icon === 'both') {
        modeIconSvg = `
          <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round"><path d="M3 8h10a3 3 0 1 0-3-3M3 12h15a3 3 0 1 1-3 3M3 16h8"/></svg>
          <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round"><path d="M12 3c3 4 5 6.5 5 9a5 5 0 0 1-10 0c0-2.5 2-5 5-9z"/></svg>
        `;
      } else if (cleaningMode.icon === 'sweep') {
        modeIconSvg = `
          <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round"><path d="M3 8h10a3 3 0 1 0-3-3M3 12h15a3 3 0 1 1-3 3M3 16h8"/></svg>
        `;
      } else {
        modeIconSvg = `
          <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round"><path d="M12 3c3 4 5 6.5 5 9a5 5 0 0 1-10 0c0-2.5 2-5 5-9z"/></svg>
        `;
      }
      topHtml = `
        <span class="k" id="mode-chip">
          ${modeIconSvg}
          ${cleaningMode.label}
        </span>
      `;
      visualHtml = `
        <img src="${IMAGES.ROBOT_CLEANING}" alt="Robot in pulizia" width="124" class="robot-cleaning-pulse" />
      `;
    }

    this.shadowRoot.innerHTML = `
      <style>${CARD_STYLES}</style>
      <div class="vacuum-card" id="card-container">
        <div class="x">${topHtml}</div>
        <div class="v">${visualHtml}</div>
      </div>
    `;

    const container = this.shadowRoot.getElementById('card-container');
    if (container && this._config.entity) {
      container.addEventListener('click', () => {
        this._handleMoreInfo(this._config.entity);
      });
    }

    const modeChip = this.shadowRoot.getElementById('mode-chip');
    if (modeChip && this._config.cleaning_mode_entity) {
      modeChip.addEventListener('click', (e) => {
        e.stopPropagation();
        this._handleMoreInfo(this._config.cleaning_mode_entity);
      });
    }
  }
}

// Registrazione Custom Elements standard (Vanilla Web Component)
customElements.define('dreame-vacuum-card-state-and-error-editor', DreameVacuumCardEditor);
customElements.define('dreame-vacuum-card-state-and-error', DreameVacuumCard);
if (!customElements.get('dreame-vacuum-state-and-error-card')) {
  customElements.define('dreame-vacuum-state-and-error-card', class extends DreameVacuumCard {});
}

// Registrazione Lovelace Card Picker
window.customCards = window.customCards || [];
window.customCards.push({
  type: 'dreame-vacuum-card-state-and-error',
  name: 'Dreame Vacuum Card (State and Error)',
  description: 'Card minimalista per robot aspirapolvere Dreame con gestione stati, errori e modalita pulizia'
});
